import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import type {PopupAttrs} from '@jetbrains/ring-ui-built/components/popup/popup'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {Ref} from 'react'
import type React from 'react'
import {
  cloneElement,
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react'

import RunningBuildUpdater from '../../../../../../containers/RunningBuildUpdater'
import type {ProjectOrBuildTypeNode} from '../../../../../../types'
import {stringifyId} from '../../../../../../types'
import {getBuildOvertimeInfo} from '../../../../../../utils/buildOvertime'
import {scrollIntoViewIfNeeded} from '../../../../../../utils/dom'
import BuildInfo from '../../../../../common/BuildInfo/BuildInfo.container'
import Popup from '../../../../../common/Popup/Popup.lazy'
import QueuedBuildInfo from '../../../../../common/QueuedBuildInfo/QueuedBuildInfo.container'
import BarBuildTypeName from '../BarBuildTypeName/BarBuildTypeName'
import {SelectionContext} from '../DependenciesTimeline.contexts'
import {useSearchMatch} from '../DependenciesTimeline.hooks'
import {getIsSearch} from '../DependenciesTimeline.selectors'
import type {TimeDataWithCoordinates} from '../DependenciesTimeline.types'
import QueuedBuildsDropdown from '../Dropdown/QueuedBuildsDropdown'
import {areRelated} from '../utils/areRelated'

import styles from './Bar.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

const MARGIN = 1
const HEIGHT = 20
export const step: number = HEIGHT + 2 * MARGIN
const {RIGHT_BOTTOM, RIGHT_TOP, BOTTOM_LEFT, TOP_LEFT} = Directions
const directions = [RIGHT_BOTTOM, RIGHT_TOP, BOTTOM_LEFT, TOP_LEFT]
const DISPLAY_NAME_THRESHOLD = 36
const TAIL_WIDTH = 80

type Handle = {
  close?: () => void
}
const BarPopup = forwardRef(function BarPopup(props: PopupAttrs, ref: Ref<Handle>) {
  useImperativeHandle(ref, () => ({
    close: props.onCloseAttempt,
  }))
  return <Popup directions={directions} {...props} />
})
type BarProps = {
  projectFilter: ProjectOrBuildTypeNode | null | undefined
  data?: ReadonlyArray<TimeDataWithCoordinates>
  datum?: TimeDataWithCoordinates
  scale?: {
    x: (arg0: number) => number
    y: (arg0: number) => number
  }
  convert: (arg0: number) => number
}

declare module 'csstype' {
  interface Properties {
    '--tc-tail-width'?: string
    '--tc-bar-width'?: string
  }
}

export function Bar({projectFilter, data, datum, scale, convert}: BarProps) {
  const {selected, focused, onHover, onFocus} = useContext(SelectionContext)
  const isFocused = focused === datum?.build.id
  const ref = useRef<HTMLButtonElement>(null)
  useEffect(() => {
    const element = ref.current

    if (isFocused && element != null) {
      element.focus()
      scrollIntoViewIfNeeded(element)
    }
  }, [isFocused])
  const popupRef = useRef<Handle>(null)
  const isSearch = useAppSelector(getIsSearch)
  const searchMatch = useSearchMatch(datum?.build.buildType)

  const popup = useMemo(
    () => (
      <BarPopup ref={popupRef}>
        {datum?.build.state === 'queued' ? (
          <QueuedBuildInfo
            key={stringifyId(datum?.build.id)}
            className={styles.buildInList}
            withPath
            buildId={datum?.build.id}
            projectOrBuildTypeFilter={projectFilter}
          />
        ) : (
          datum?.build.id != null && (
            <BuildInfo
              inlineQueueInfo
              withPath
              hideProgress
              buildId={datum.build.id}
              projectOrBuildTypeFilter={projectFilter}
              dependenciesRange={datum.dependenciesRange}
              withFetchBuildData
              groupOwnQueueReasons
            />
          )
        )}
      </BarPopup>
    ),
    [datum?.build.state, datum?.build.id, datum?.dependenciesRange, projectFilter],
  )

  if (scale == null || datum == null || data == null) {
    return null
  }

  const {isOvertime} = getBuildOvertimeInfo(datum.build?.['running-info'])

  const queued = scale.y(datum.y0)
  const start = scale.y(convert(datum.start))
  const finish = scale.y(datum.y)
  const current = datum.current != null ? scale.y(convert(datum.current)) : finish
  const estimate = datum.estimate != null ? scale.y(convert(datum.estimate)) : current
  const unknownFinish = datum.finish === Infinity
  const timeWidth = finish - queued - 2 * MARGIN
  const width = Math.max(timeWidth, 1)
  const barStart = queued + MARGIN
  const progressOffset = start - barStart
  const barClasses = classNames(
    styles.bar,
    datum.build.canceledInfo != null
      ? styles.canceled
      : datum.build.status === 'SUCCESS'
        ? styles.success
        : styles.failed,
    {
      [styles.queued]: datum.build.state === 'queued',
      [styles.incomplete]: datum.build.state === 'running',
      [styles.unknownStart]: datum.start === Infinity,
      [styles.unknownFinish]: unknownFinish,
      [styles.selected]: selected === datum.build.id,
      [styles.fade]: isSearch
        ? !searchMatch.matched
        : selected != null && !areRelated(datum.build.id, selected, data),
      [styles.failedToStart]: datum.build.failedToStart,
    },
  )

  const onKeyDown = (e: React.KeyboardEvent) => {
    const itemToFocus: TimeDataWithCoordinates | null | undefined = (() => {
      switch (e.key) {
        case 'ArrowLeft':
          e.stopPropagation()
          return data.find(({build}) => build.id === datum.lastDependencyId)

        case 'ArrowRight':
          const firstDependant = data.find(({build}) => {
            const dependencies = build['snapshot-dependencies']?.build ?? []
            return dependencies.some(({id}) => id === datum.build.id)
          })

          if (firstDependant != null) {
            return firstDependant
          }

          const laterBuilds = data.filter(({y0}) => y0 >= datum.y)

          const getXOffset = ({x}: TimeDataWithCoordinates) => Math.abs(x - datum.x)

          if (laterBuilds.length > 0) {
            const minXOffset = Math.min(...laterBuilds.map(getXOffset))
            return laterBuilds.find(build => getXOffset(build) === minXOffset)
          }

          return null

        case 'ArrowUp':
          const concurrentBuildsAbove = data.filter(
            ({x, y0, y}) => x < datum.x && y0 < datum.y && y > datum.y0,
          )
          return concurrentBuildsAbove[concurrentBuildsAbove.length - 1]

        case 'ArrowDown':
          const concurrentBuildsBelow = data.filter(
            ({x, y0, y}) => x > datum.x && y0 < datum.y && y > datum.y0,
          )
          return concurrentBuildsBelow[0]

        default:
          return null
      }
    })()

    if (itemToFocus != null) {
      onFocus(itemToFocus)
      e.stopPropagation()
      e.preventDefault()

      if (popupRef.current?.close != null) {
        popupRef.current.close()
      }
    }
  }

  const style = unknownFinish
    ? {
        minWidth: width + TAIL_WIDTH + 2,
      }
    : {
        width,
      }
  const nameStyle = unknownFinish
    ? {}
    : {
        maxWidth: width,
      }
  const enoughWidth = unknownFinish || width >= DISPLAY_NAME_THRESHOLD
  const name = (
    <div
      className={classNames(styles.name, {
        [styles.nameHidden]: !enoughWidth,
      })}
    >
      {isOvertime && <SvgIcon icon="overtime" className={styles.overtimeIcon} />}
      {datum.build.state === 'queued' && (
        <SvgIcon icon="hourglass" className={styles.hourglassIcon} />
      )}
      {datum.build.canceledInfo != null && (
        <SvgIcon icon="cancel" className={styles.canceledIcon} />
      )}
      {datum.build.failedToStart === true && (
        <SvgIcon icon="warning-12px" className={styles.failedToStartIcon} />
      )}
      <BarBuildTypeName buildTypeId={datum?.build.buildType} width={width} />
    </div>
  )
  const anchor = (
    <button
      type="button"
      ref={ref}
      onMouseEnter={() => onHover(datum.build.id)}
      onFocus={() => {
        if (!isFocused) {
          onFocus(datum)
        }
      }}
      onMouseLeave={() => onHover(null)}
      onBlur={() => {
        if (isFocused) {
          onFocus(null)
        }
      }}
      onKeyDown={onKeyDown}
      className={barClasses}
      data-build-id={datum.build.id}
    >
      {datum.build.state !== 'finished' && !unknownFinish && (
        <div
          className={styles.yetToRun}
          style={{
            width: datum.build.state === 'running' ? finish - current : finish - start,
          }}
        />
      )}
      {name}
      {datum.build.state !== 'queued' && (
        <div
          className={classNames(styles.progress, {
            [styles.running]: datum.build.state === 'running',
          })}
          style={{
            left: progressOffset,
            width: isOvertime ? estimate - start : current - start,
          }}
        >
          {enoughWidth &&
            cloneElement(name, {
              'aria-hidden': true,
              style: {...nameStyle, left: -progressOffset},
            })}
        </div>
      )}
    </button>
  )

  return (
    <div
      className={styles.barWrapper}
      style={{
        top: datum.x * step,
        left: barStart,
        '--tc-tail-width': `${TAIL_WIDTH}px`,
        '--tc-bar-width': `${width}px`,
      }}
    >
      {datum.build.state === 'running' && <RunningBuildUpdater buildId={datum.build.id} />}
      <Dropdown anchor={anchor} style={style} className={styles.barDropdown}>
        {popup}
      </Dropdown>
      <QueuedBuildsDropdown builds={datum.queuedDependents} projectFilter={projectFilter} />
    </div>
  )
}
