import type {BuildId} from '../../../../../../types'
import type {TimeDataWithCoordinates} from '../DependenciesTimeline.types'

const isAncestry = (
  a: BuildId,
  b: BuildId,
  data: ReadonlyArray<TimeDataWithCoordinates>,
): boolean => {
  if (a === b) {
    return true
  }

  const buildA = data.find(({build}) => build.id === a)
  const dependencies = buildA?.build['snapshot-dependencies']?.build ?? []
  return buildA != null && dependencies.some(build => isAncestry(build.id!, b, data))
}
export const areRelated = (a: BuildId, b: BuildId, data: ReadonlyArray<TimeDataWithCoordinates>) =>
  isAncestry(a, b, data) || isAncestry(b, a, data)
