import classNames from 'classnames'

import styles from './Gap.module.css'

export const GAP_WIDTH = 18

export type GapType = {
  from: number
  to: number
  length: number
}
export type GapData = GapType & {
  accumulated: number
  x: number
  y: number
}
type GapProps = {
  datum?: GapData
  scale?: {
    x: (arg0: number) => number
    y: (arg0: number) => number
  }
  preview?: boolean
}

const getOffset = ({datum, scale}: GapProps) => {
  if (datum == null || scale == null) {
    return 0
  }

  return scale.y(datum.y) - GAP_WIDTH / 2
}

export function Gap(props: GapProps) {
  return (
    <div
      className={classNames(styles.gap, {
        [styles.previewGap]: props.preview,
      })}
      style={{
        left: getOffset(props),
      }}
    />
  )
}
