import SearchInput from '../../../../../common/SearchInput/SearchInput'
import {getSearch} from '../DependenciesTimeline.selectors'
import {dependenciesTimelineSearch} from '../DependenciesTimeline.slice'

import styles from './DependenciesTimelineSearch.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

function DependenciesTimelineSearch() {
  const search = useAppSelector(getSearch)
  const dispatch = useAppDispatch()
  const setSearch = (value: string) => dispatch(dependenciesTimelineSearch.actions.set(value))
  return (
    <SearchInput
      className={styles.search}
      placeholder="Search"
      value={search}
      onChange={e => setSearch(e.currentTarget.value)}
      onClear={() => setSearch('')}
    />
  )
}

export default DependenciesTimelineSearch
