import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import memoize from '@jetbrains/ring-ui-built/components/global/memoize'
import classNames from 'classnames'
import type {Duration} from 'date-fns'
import {add as addDuration} from 'date-fns/add'
import throttle from 'lodash/throttle'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useLocator} from '../../../../../contexts/locator'
import {useBuildId} from '../../../../../hooks/routes'
import {useIsAutodetectTimeZone} from '../../../../../hooks/useIsAutodetectTimeZone'
import {useMeasureSelector} from '../../../../../hooks/useMeasure'
import {useObjectSlice} from '../../../../../hooks/useSlice'
import {getSingleBuildArg} from '../../../../../rest/builds'
import {getBuildLocator} from '../../../../../rest/locators'
import {
  getBuild,
  getBuildsReady,
  getBuildType,
  getSnapshotDependencies,
  getSnapshotDependenciesLoaded,
  makeGetBuilds,
} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {BuildId, NormalizedBuild, SnapshotDependenciesIDList} from '../../../../../types'
import {getProjectBuildTypeFilter} from '../../../../../types'
import {internalProps} from '../../../../../types/BS_types'
import {displayDate, parseDateToObj} from '../../../../../utils/dateTimeUtils'
import {emptyArray} from '../../../../../utils/empty'
import {notNull} from '../../../../../utils/guards'
import stableSort from '../../../../../utils/stableSort'
import BuildQueueInfo from '../../../../common/BuildQueueInfo/BuildQueueInfo.container'
import Loader from '../../../../common/Loader/Loader'

import Chart from './Chart/Chart'
import {SelectionContext} from './DependenciesTimeline.contexts'
import type {Domain, TimeData, TimeDataWithCoordinates} from './DependenciesTimeline.types'
import type {GapData, GapType} from './Gap/Gap'
import {GAP_WIDTH} from './Gap/Gap'
import Legend from './Legend/Legend'
import Preview from './Preview/Preview'
import useDomain, {stringifyRange} from './useDomain'
import {getFinishDate, getTimeData} from './utils/getTimeData'

import styles from './DependenciesTimeline.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

// eslint-disable-next-line @typescript-eslint/no-magic-numbers
const TIME_PADDING = 60 * 60 * 1000 // An hour

const THROTTLE_TIME = 1000

const isComposite = (build: NormalizedBuild | null | undefined) =>
  build?.composite === true && Boolean(build['snapshot-dependencies']?.build?.length)
const MIN_WIDTH = 756
const durationToMilliseconds = (duration: Duration) => +addDuration(0, duration)
const maxTickSteps = [
  {
    step: durationToMilliseconds({
      weeks: 2,
    }),
    breakpoint: durationToMilliseconds({
      weeks: 5.5,
    }),
  },
  {
    step: durationToMilliseconds({
      days: 2,
    }),
    breakpoint: durationToMilliseconds({
      weeks: 2,
    }),
  },
  {
    step: durationToMilliseconds({
      days: 1,
    }),
    breakpoint: durationToMilliseconds({
      weeks: 1,
    }),
  },
  {
    step: durationToMilliseconds({
      hours: 12,
    }),
    breakpoint: durationToMilliseconds({
      days: 3.5,
    }),
  },
  {
    step: durationToMilliseconds({
      hours: 6,
    }),
    breakpoint: durationToMilliseconds({
      days: 1.5,
    }),
  },
  {
    step: durationToMilliseconds({
      hours: 3,
    }),
    breakpoint: durationToMilliseconds({
      hours: 19,
    }),
  },
  {
    step: durationToMilliseconds({
      hours: 1,
    }),
    breakpoint: durationToMilliseconds({
      hours: 7.5,
    }),
  },
  {
    step: durationToMilliseconds({
      minutes: 30,
    }),
    breakpoint: durationToMilliseconds({
      hours: 1.5,
    }),
  },
  {
    step: durationToMilliseconds({
      minutes: 10,
    }),
    breakpoint: durationToMilliseconds({
      minutes: 24,
    }),
  },
  {
    step: durationToMilliseconds({
      minutes: 2,
    }),
    breakpoint: durationToMilliseconds({
      minutes: 20,
    }),
  },
  {
    step: durationToMilliseconds({
      minutes: 1,
    }),
    breakpoint: durationToMilliseconds({
      minutes: 7.5,
    }),
  },
  {
    step: durationToMilliseconds({
      seconds: 30,
    }),
    breakpoint: durationToMilliseconds({
      minutes: 1.5,
    }),
  },
  {
    step: durationToMilliseconds({
      seconds: 10,
    }),
    breakpoint: durationToMilliseconds({
      seconds: 24,
    }),
  },
  {
    step: durationToMilliseconds({
      seconds: 2,
    }),
    breakpoint: durationToMilliseconds({
      seconds: 20,
    }),
  },
  {
    step: durationToMilliseconds({
      seconds: 1,
    }),
    breakpoint: 0,
  },
]

const getGapUnit = (duration: number) =>
  maxTickSteps.find(({breakpoint}) => duration > breakpoint)?.step ?? maxTickSteps[0].step
const attachSnapshotDependencies = (
  build: NormalizedBuild,
  snapshotDependencies: SnapshotDependenciesIDList,
): NormalizedBuild =>
  Object.assign({}, build, {
    'snapshot-dependencies': {
      build: (snapshotDependencies[build.id] ?? emptyArray).map(id => ({
        id,
      })),
    },
  })
const DELAY = 300 //ms
const MIN_MAX_X = 16
type State = {
  selected?: BuildId | null
  focused?: BuildId | null
}
type PayloadMap = {
  hover: BuildId | null
  focus: BuildId | null | undefined
}
function DependenciesTimeline() {
  const locator = useLocator()
  const buildId = useBuildId()!
  const self = useAppSelector(state => getBuild(state, buildId))
  const projectId = useAppSelector(state => getBuildType(state, self?.buildType)?.projectId)
  const getBuilds = useMemo(makeGetBuilds, [])
  const builds = useAppSelector(state => getBuilds(state, locator))
  restApi.endpoints.getBuildNormalized.useQuerySubscription(
    getSingleBuildArg(getBuildLocator(buildId), {withSnapshotDependencies: true}),
  )
  const ready = useAppSelector(
    state =>
      self != null &&
      getSnapshotDependenciesLoaded(state, buildId) &&
      getBuildsReady(state, locator),
  )
  const selfQueuedDate = self?.queuedDate ?? ''
  const snapshotDependencies = useAppSelector(getSnapshotDependencies)
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const {measureRef, result: width} = useMeasureSelector(
    {
      client: true,
    },
    contentRect => contentRect.client?.width,
    undefined,
  )
  const projectFilter = getProjectBuildTypeFilter({
    projectId,
  })
  const allBuilds: ReadonlyArray<NormalizedBuild> = useMemo(
    () =>
      ready && self != null
        ? [self, ...builds].map(build => attachSnapshotDependencies(build, snapshotDependencies))
        : emptyArray,
    [ready, self, snapshotDependencies, builds],
  )
  const timeData = useMemo(() => {
    const data = allBuilds.map(getTimeData(isAutodetectTimeZone)).filter(notNull)
    const currents = data.map(datum => datum.current).filter(notNull)
    const averageCurrent = currents.reduce((a, b) => a + b, 0) / currents.length
    return data.map(datum => ({...datum, current: datum.current != null ? averageCurrent : null}))
  }, [isAutodetectTimeZone, allBuilds])
  const [throttledFinish, setThrottledFinish] = useState<Record<number, number>>({})
  const setTrottledFinishCallback = useMemo(
    () => throttle(setThrottledFinish, THROTTLE_TIME, {leading: true, trailing: true}),
    [],
  )
  useEffect(() => {
    if (timeData.length > 0) {
      setTrottledFinishCallback(
        Object.fromEntries(timeData.map(item => [item.build.id, item.finish])),
      )
    }
  }, [setTrottledFinishCallback, timeData])
  const [showCompositeBuilds, setShowCompositeBuilds] = useState(false)
  const filteredTimeData = useMemo(
    () => (showCompositeBuilds ? timeData : timeData.filter(({build}) => !isComposite(build))),
    [showCompositeBuilds, timeData],
  )
  const firstQueued = Math.min(...filteredTimeData.map(item => item.queued))
  const lastFinished = Math.max(...filteredTimeData.map(item => item.lastKnown))
  const displayedGaps = useMemo(() => {
    const allGaps = stableSort(filteredTimeData, (a, b) => a.queued - b.queued).reduce<{
      lastFinish: number
      gaps: GapType[]
    }>(
      ({lastFinish, gaps}, {queued, finish}) => {
        const from = lastFinish
        const to = queued
        const length = to - from
        return {
          lastFinish: Math.max(lastFinish, finish),
          gaps:
            length > 0
              ? [
                  ...gaps,
                  {
                    from,
                    to,
                    length,
                  },
                ]
              : gaps,
        }
      },
      {
        lastFinish: firstQueued,
        gaps: [],
      },
    ).gaps

    if (allGaps.length === 0) {
      return emptyArray as GapData[]
    }

    const duration = lastFinished - firstQueued - allGaps.reduce((acc, {length}) => acc + length, 0)
    const gapUnit = getGapUnit(duration)
    const gapWidth = (duration * GAP_WIDTH) / MIN_WIDTH
    return allGaps
      .filter(({length}) => length >= gapUnit + gapWidth)
      .map(({from, to, length}) => {
        const rest = gapWidth + ((length - gapWidth) % gapUnit)
        return {
          from: from + rest / 2,
          to: to - rest / 2,
          length: length - rest,
        }
      })
      .reduce<GapData[]>((acc, gap) => {
        const lastItem: GapData | null | undefined = acc[acc.length - 1]
        const accumulated = lastItem?.accumulated ?? 0
        return [
          ...acc,
          {...gap, x: 0, y: gap.from - accumulated, accumulated: accumulated + gap.length},
        ]
      }, [])
  }, [filteredTimeData, firstQueued, lastFinished])
  const convert = useCallback(
    (time: number, back = false) => {
      const gaps = displayedGaps.filter(gap => (back ? gap.y : gap.to) < time)
      const accumulated = gaps[gaps.length - 1]?.accumulated ?? 0
      return back ? time + accumulated : time - accumulated
    },
    [displayedGaps],
  )
  const data = useMemo(() => {
    const result: TimeDataWithCoordinates[] = []
    const timeDataHash = Object.fromEntries(timeData.map(item => [item.build.id, item]))
    const getDependencies = memoize((build: NormalizedBuild) => {
      const dependencies: TimeData[] = []

      function addDependencies(otherBuild: NormalizedBuild) {
        for (const {id} of otherBuild['snapshot-dependencies']?.build ?? []) {
          const dependency = timeDataHash[id!]

          if (dependency == null) {
            continue
          }

          if (!showCompositeBuilds && isComposite(dependency.build)) {
            addDependencies(dependency.build)
          } else {
            dependencies.push(dependency)
          }
        }
      }

      addDependencies(build)
      return dependencies
    })
    const getLatestDependency = memoize((build: NormalizedBuild) => {
      let latestDependency = null
      let latestFinish = -Infinity

      for (const dependency of getDependencies(build)) {
        const finish = getFinishDate(dependency.build)

        if (finish > latestFinish) {
          latestDependency = dependency
          latestFinish = finish
        }
      }

      return latestDependency
    })
    const getReadyDependents = memoize((build: NormalizedBuild) =>
      timeData.filter(datum => {
        if (isComposite(datum.build)) {
          return false
        }

        return getLatestDependency(datum.build)?.build.id === build.id
      }),
    )

    function add(datum: TimeData) {
      const {queued, finish, lastKnown, lastDependencyId, ownQueued} = datum
      const concurrentBuilds = result.filter(item => item.queued < finish && item.finish > queued)
      const lastDependencyX = lastDependencyId
        ? result.find(item => item.build.id === lastDependencyId)?.x
        : 0
      const x = Math.max(lastDependencyX ?? 0, ...concurrentBuilds.map(item => item.x + 1))
      result.push({
        ...datum,
        x,
        y0: convert(queued),
        y: convert(Math.max(queued, lastKnown)),
        dependenciesRange:
          ownQueued != null && ownQueued < queued
            ? stringifyRange([convert(ownQueued), convert(queued)])
            : '',
      })
    }

    const addAll = (items: ReadonlyArray<TimeData>) =>
      stableSort(
        items,
        (a, b) =>
          a.queued - b.queued ||
          throttledFinish[b.build.id] - throttledFinish[a.build.id] ||
          getReadyDependents(b.build).length - getReadyDependents(a.build).length,
      ).forEach(item => {
        const readyDependents = getReadyDependents(item.build).map(datum => ({
          ...datum,
          ownQueued: datum.queued,
          queued: Math.max(datum.queued, item.finish),
          lastDependencyId: item.build.id,
        }))

        if (item.finish === Infinity) {
          add({...item, queuedDependents: readyDependents.map(dependent => dependent.build)})
        } else {
          add(item)
          addAll(readyDependents)
        }
      }, result)

    if (showCompositeBuilds) {
      addAll(timeData.filter(item => isComposite(item.build)))
    }
    const roots = timeData.filter(item => getDependencies(item.build).length === 0)
    addAll(roots)
    return result
  }, [timeData, showCompositeBuilds, convert, throttledFinish])
  const [state, {hover, focus}] = useObjectSlice<State, PayloadMap>(
    {
      hover: ({focused}, selected) => ({
        selected: selected ?? focused,
      }),
      focus: (_, focused) => ({
        selected: focused,
        focused,
      }),
    },
    {},
  )
  const {selected, focused} = state
  const hasUnknownFinish = data.some(item => item.finish === Infinity)
  const lastFinishedWithTail = convert(lastFinished) + (hasUnknownFinish ? TIME_PADDING : 0)
  const maxX = Math.max(MIN_MAX_X, ...data.map(datum => datum.x))
  const selfQueued = convert(Number(parseDateToObj(selfQueuedDate, isAutodetectTimeZone)))
  const nonSelfBuilds = filteredTimeData.filter(item => item.build.id !== self?.id)
  const lastNonSelfFinished = hasUnknownFinish
    ? lastFinishedWithTail
    : nonSelfBuilds.length > 0
      ? convert(Math.max(...nonSelfBuilds.map(item => item.finish)))
      : null
  const [domain, {setYDomain, adjustYDomain}] = useDomain({
    ready,
    maxX,
    firstQueued,
    selfQueued,
    lastNonSelfFinished,
    lastFinished: lastFinishedWithTail,
  })
  const timeoutRef = useRef<number>()
  const onHover = useCallback(
    (hoveredBuildId: BuildId | null) => {
      if (hoveredBuildId != null) {
        if (timeoutRef.current != null) {
          clearTimeout(timeoutRef.current)
        }

        hover(hoveredBuildId)
      } else {
        timeoutRef.current = window.setTimeout(() => hover(null), DELAY)
      }
    },
    [hover],
  )
  const onFocus = useCallback(
    (datum: TimeDataWithCoordinates | null) => {
      focus(datum?.build.id)
      adjustYDomain(datum)
    },
    [adjustYDomain, focus],
  )
  const context = useMemo(
    () => ({
      selected,
      focused,
      onHover,
      onFocus,
    }),
    [onFocus, focused, onHover, selected],
  )
  const outerContainerClasses = classNames(styles.outerContainer, {
    [styles.invisible]: width == null || width === 0,
  })
  const fullDomain: Domain = useMemo(
    () => ({
      x: [0, maxX],
      y: [firstQueued, lastFinishedWithTail],
    }),
    [lastFinishedWithTail, firstQueued, maxX],
  )
  const limitedDomain: Domain | null = useMemo(
    () =>
      domain != null
        ? {
            x: domain.x,
            y: [
              Math.max(Number(domain.y[0]), Number(fullDomain.y[0])),
              Math.min(Number(domain.y[1]), Number(fullDomain.y[1])),
            ],
          }
        : null,
    [domain, fullDomain],
  )
  const onDomainChange = useCallback(({y}: Domain) => setYDomain(y), [setYDomain])
  return (
    <div className={outerContainerClasses}>
      {self != null && self.state !== 'queued' && (
        <BuildQueueInfo
          titleClassName={styles.queueInfo}
          reasonsClassName={styles.queueInfo}
          buildId={self.id}
          inline
          aside={
            self.startDate != null && (
              <span className={styles.started}>
                {'Started at '}
                {displayDate(self.startDate, isAutodetectTimeZone, true)}
              </span>
            )
          }
          dependenciesRange={
            lastNonSelfFinished != null && selfQueued < lastNonSelfFinished
              ? stringifyRange([selfQueued, lastNonSelfFinished])
              : null
          }
        />
      )}
      <div ref={measureRef} />
      {internalProps['teamcity.ui.compositeBuildsOnTimeline.enabled'] &&
        timeData.some(item => isComposite(item.build)) && (
          <div>
            <Checkbox
              checked={showCompositeBuilds}
              onChange={e => setShowCompositeBuilds(e.currentTarget.checked)}
            >
              {'Show composite builds'}
            </Checkbox>
          </div>
        )}
      {ready && (width != null || process.env.NODE_ENV === 'test') && limitedDomain != null ? (
        data.length > 0 && (
          <SelectionContext.Provider value={context}>
            <Legend />
            <Preview
              maxX={maxX}
              width={width}
              data={data}
              gaps={displayedGaps}
              domain={limitedDomain}
              fullDomain={fullDomain}
              onDomainChange={onDomainChange}
            />
            <Chart
              fullDomain={fullDomain}
              convert={convert}
              projectFilter={projectFilter}
              maxX={maxX}
              width={width}
              data={data}
              gaps={displayedGaps}
              domain={limitedDomain}
              onDomainChange={onDomainChange}
              utcOffset={parseDateToObj(
                data[0].build.queuedDate ?? '',
                isAutodetectTimeZone,
              ).utcOffset()}
            />
          </SelectionContext.Provider>
        )
      ) : (
        <Loader />
      )}
    </div>
  )
}
export default DependenciesTimeline
