import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo} from 'react'

import {stringifyId} from '../../../../../../types'
import type {NormalizedBuild, ProjectOrBuildTypeNode} from '../../../../../../types'
import Popup from '../../../../../common/Popup/Popup.lazy'
import QueuedBuildInfo from '../../../../../common/QueuedBuildInfo/QueuedBuildInfo.container'

import styles from './QueuedBuildsDropdown.module.css'

type Props = {
  builds: ReadonlyArray<NormalizedBuild> | void
  projectFilter: ProjectOrBuildTypeNode | null | undefined
}

function QueuedBuildsDropdown({builds = [], projectFilter}: Props) {
  const count = builds.length
  return count > 0 ? (
    <Dropdown
      hoverMode
      anchor={
        <IconButton className={styles.hourglass} iconClassName={styles.statusIcon} icon="hourglass">
          {builds.length}
        </IconButton>
      }
    >
      <Popup className={styles.buildsPopup}>
        {builds.map(build => (
          <QueuedBuildInfo
            key={stringifyId(build.id)}
            className={styles.buildInList}
            withPath
            buildId={build.id}
            projectOrBuildTypeFilter={projectFilter}
          />
        ))}
      </Popup>
    </Dropdown>
  ) : null
}

export default memo(QueuedBuildsDropdown)
