import classNames from 'classnames'
import {memo} from 'react'

import type {BuildTypeId} from '../../../../../../types'
import Highlight from '../../../../../common/Highlight/Highlight'
import {useSearchMatch} from '../DependenciesTimeline.hooks'

import styles from './BarBuildTypeName.module.css'

const DISPLAY_PROJECT_NAME_THRESHOLD = 70

interface Props {
  buildTypeId: BuildTypeId | undefined
  width: number
}

function BarBuildTypeName(props: Props) {
  const {buildTypeId, width} = props
  const searchMatch = useSearchMatch(buildTypeId)

  return (
    <div className={styles.container}>
      <div className={styles.innerContainer}>
        {searchMatch.projectName != null && DISPLAY_PROJECT_NAME_THRESHOLD < width && (
          <>
            <div className={classNames(styles.projectName, styles.ellipsis)}>
              <Highlight
                string={searchMatch.projectName}
                matches={searchMatch.projectNameSearch.matches}
              />
            </div>
            &nbsp;{'/'}&nbsp;
          </>
        )}
        <div className={classNames(styles.buildTypeName, styles.ellipsis)}>
          <Highlight
            string={searchMatch.buildTypeName}
            matches={searchMatch.buildTypeNameSearch.matches}
          />
        </div>
      </div>
    </div>
  )
}

export default memo(BarBuildTypeName)
