import {memo} from 'react'
import {VictoryAxis, VictoryBar, VictoryChart, VictoryBrushContainer} from 'victory'

import type {ChartProps} from '../DependenciesTimeline.types'
import {Gap} from '../Gap/Gap'
import PreviewBar from '../PreviewBar/PreviewBar'

import styles from './Preview.module.css'

const STEP = 3
const PADDING = 8
const DOMAIN_PADDING = 2

type BrushProps = {
  datum?: {
    y0: number
    y: number
  }
  scale?: {
    y: (arg0: number) => number
  }
  parentHeight?: number
}

function Brush({datum, scale, parentHeight = 0}: BrushProps) {
  if (datum == null || scale == null) {
    return null
  }

  const y0 = scale.y(datum.y0)
  const y = scale.y(datum.y)
  return <rect className={styles.brush} y={1} height={parentHeight - 2} x={y0} width={y - y0} />
}

function BrushBorder({datum, scale}: BrushProps) {
  if (datum == null || scale == null) {
    return null
  }

  const y0 = scale.y(datum.y0)
  const y = scale.y(datum.y)
  // noinspection JSSuspiciousNameCombination
  return (
    <div
      className={styles.brushBorder}
      style={{
        left: y0,
        width: y - y0,
      }}
    />
  )
}

function Nothing() {
  return null
}

const emptyFragment = <></>

declare module 'victory-brush-container' {
  interface VictoryBrushContainerProps {
    mouseMoveThreshold?: number
  }
}

function Preview({maxX, width, data, gaps, domain, fullDomain, onDomainChange}: ChartProps) {
  const height = maxX * STEP + 2 * PADDING
  const brushData = domain && [
    {
      y0: domain.y[0],
      y: domain.y[1],
    },
  ]
  return (
    <div className={styles.previewContainer}>
      <div
        className={styles.preview}
        style={{
          height,
        }}
      >
        <VictoryChart
          horizontal
          width={width}
          height={height}
          domain={{
            x: [Number(domain.x[0]) - DOMAIN_PADDING, Number(domain.x[1]) + DOMAIN_PADDING],
            y: fullDomain.y,
          }}
          padding={{
            top: 2,
            right: 0,
            bottom: 2,
            left: 0,
          }}
          containerComponent={
            <VictoryBrushContainer
              title="Dependencies timeline preview"
              brushDimension="y"
              defaultBrushArea="move"
              brushDomain={domain}
              onBrushDomainChange={onDomainChange}
              brushStyle={{
                fillOpacity: 0,
              }}
              responsive={false}
              mouseMoveThreshold={2}
            />
          }
        >
          <VictoryAxis invertAxis groupComponent={<Nothing />} />
          {brushData && (
            <VictoryBar data={brushData} dataComponent={<Brush parentHeight={height} />} />
          )}
          <VictoryBar data={data} barWidth={2} dataComponent={<PreviewBar />} />
        </VictoryChart>
        <VictoryChart
          horizontal
          width={width}
          padding={0}
          domain={fullDomain}
          containerComponent={emptyFragment}
        >
          <VictoryAxis invertAxis groupComponent={<Nothing />} />
          <VictoryBar groupComponent={emptyFragment} dataComponent={<Gap preview />} data={gaps} />
          {brushData && (
            <VictoryBar
              groupComponent={emptyFragment}
              data={brushData}
              dataComponent={<BrushBorder />}
            />
          )}
        </VictoryChart>
      </div>
    </div>
  )
}

export default memo(Preview)
