import type {NormalizedBuild} from '../../../../../../types'
import {parseDateToObj} from '../../../../../../utils/dateTimeUtils'
import type {TimeData} from '../DependenciesTimeline.types'

export const getFinishDate = (
  {startDate, finishDate, finishEstimate, 'running-info': runningInfo}: NormalizedBuild,
  isAutodetectTimeZone?: boolean,
) => {
  if (finishDate != null) {
    return Number(parseDateToObj(finishDate, isAutodetectTimeZone))
  }

  if (startDate != null && runningInfo != null) {
    const {elapsedSeconds, leftSeconds} = runningInfo
    return leftSeconds != null
      ? Number(
          parseDateToObj(startDate, isAutodetectTimeZone).add(
            elapsedSeconds + leftSeconds,
            'seconds',
          ),
        )
      : Infinity
  }

  if (finishEstimate != null) {
    return Number(parseDateToObj(finishEstimate))
  }

  return Infinity
}
const getCurrentDate = (
  {startDate, 'running-info': runningInfo}: NormalizedBuild,
  isAutodetectTimeZone: boolean | null | undefined,
) => {
  if (startDate != null && runningInfo != null) {
    return Number(
      parseDateToObj(startDate, isAutodetectTimeZone).add(runningInfo.elapsedSeconds, 'seconds'),
    )
  }

  return null
}

const getEstimateDate = (
  {startDate, 'running-info': runningInfo}: NormalizedBuild,
  isAutodetectTimeZone: boolean | null | undefined,
) => {
  if (startDate != null && runningInfo != null) {
    return Number(
      parseDateToObj(startDate, isAutodetectTimeZone).add(
        runningInfo.estimatedTotalSeconds,
        'seconds',
      ),
    )
  }

  return null
}
export const getTimeData =
  (isAutodetectTimeZone?: boolean) =>
  (build: NormalizedBuild): TimeData | null | undefined => {
    const {queuedDate, startDate, startEstimate} = build

    if (queuedDate == null) {
      return null
    }

    const queued = Number(parseDateToObj(queuedDate, isAutodetectTimeZone))
    const startDateOrEstimate = startDate ?? startEstimate
    const start =
      startDateOrEstimate != null
        ? Number(parseDateToObj(startDateOrEstimate, isAutodetectTimeZone))
        : Infinity
    const current = getCurrentDate(build, isAutodetectTimeZone)
    const finish = getFinishDate(build, isAutodetectTimeZone)
    const estimate = getEstimateDate(build, isAutodetectTimeZone)
    const lastKnown =
      [finish, current, start].find(value => value != null && value < Infinity) ?? queued
    return {
      build,
      queued,
      finish,
      current,
      start,
      estimate,
      lastKnown,
    }
  }
