import classNames from 'classnames'
import moment from 'moment'
import {memo, useCallback, useEffect, useRef} from 'react'
import {VictoryAxis, VictoryBar, VictoryChart, VictoryLabel, VictoryZoomContainer} from 'victory'

import type {ProjectOrBuildTypeNode} from '../../../../../../types'
import {Bar, step} from '../Bar/Bar'
import type {ChartProps, Domain} from '../DependenciesTimeline.types'
import {Gap} from '../Gap/Gap'

import styles from './Chart.module.css'

const TICK_SIZE = 8
const TICK_SPACING = 80

function Nothing() {
  return null
}

const emptyFragment = <></>

type Props = ChartProps & {
  fullDomain: Domain
  convert: (time: number, back?: boolean) => number
  projectFilter: ProjectOrBuildTypeNode | null | undefined
  utcOffset: number
}

function Chart({
  fullDomain,
  convert,
  projectFilter,
  maxX,
  width,
  data,
  gaps,
  domain,
  onDomainChange,
  utcOffset,
}: Props) {
  const pannable =
    domain != null && (domain.y[0] > fullDomain.y[0] || domain.y[1] < fullDomain.y[1])
  const convertTick = (tick: Date) => moment(convert(tick.getTime(), true))
  const tickFormat = (tick: Date, index: number, ticks: ReadonlyArray<Date>) => {
    const current = convertTick(tick).utcOffset(utcOffset)
    const previous = index > 0 ? convertTick(ticks[index - 1]).utcOffset(utcOffset) : null

    if (previous != null && current.isSame(previous, 'minute')) {
      return current.format(`:ss`)
    }

    const addDay = previous == null || !current.isSame(previous, 'day')
    return current.utcOffset(utcOffset).format(`${addDay ? 'D MMM[\n]' : ''}LT`)
  }
  const wheelVictoryZoomContainerHandler = useCallback(
    (event: WheelEvent) => event.stopImmediatePropagation(),
    [],
  )
  const victoryZoomContainerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const victoryZoomContainerRefCurrent = victoryZoomContainerRef?.current

    if (victoryZoomContainerRefCurrent) {
      victoryZoomContainerRefCurrent.addEventListener('wheel', wheelVictoryZoomContainerHandler, {
        capture: true,
      })
    }

    return () => {
      if (victoryZoomContainerRefCurrent) {
        victoryZoomContainerRefCurrent.removeEventListener(
          'wheel',
          wheelVictoryZoomContainerHandler,
        )
      }
    }
  }, [wheelVictoryZoomContainerHandler])

  return (
    <div
      className={classNames(styles.container, {
        [styles.pannable]: pannable,
      })}
      data-dependencies-timeline
    >
      <VictoryChart
        scale={{
          y: 'time',
        }}
        horizontal
        domain={fullDomain}
        containerComponent={
          <VictoryZoomContainer
            title="Dependencies timeline"
            zoomDomain={domain}
            onZoomDomainChange={onDomainChange}
            className={styles.victoryContainer}
            containerRef={victoryZoomContainerRef}
            responsive={false}
            zoomDimension="y"
            allowZoom={false}
          />
        }
        padding={0}
        width={width}
        height={(maxX + 1) * step}
      >
        <VictoryAxis
          dependentAxis
          orientation="top"
          style={{
            axis: {
              stroke: 'transparent',
            },
            grid: {
              stroke: 'var(--ring-line-color)',
            },
            ticks: {
              stroke: 'var(--ring-line-color)',
              size: TICK_SIZE,
            },
            tickLabels: {
              fontFamily: 'inherit',
              fontSize: 12,
              lineHeight: 'var(--ring-line-height-lowest)',
              fill: 'var(--ring-secondary-color)',
              padding: 4,
            },
          }}
          tickLabelComponent={<VictoryLabel lineHeight={1.33} />}
          tickCount={width != null ? Math.floor(width / TICK_SPACING) : undefined}
          tickFormat={tickFormat}
        />
      </VictoryChart>
      <VictoryChart
        horizontal
        containerComponent={emptyFragment}
        padding={0}
        width={width}
        domain={domain}
      >
        <VictoryAxis invertAxis groupComponent={<Nothing />} />
        <VictoryBar
          groupComponent={emptyFragment}
          dataComponent={<Bar projectFilter={projectFilter} convert={convert} />}
          data={data}
        />
        <VictoryBar groupComponent={emptyFragment} dataComponent={<Gap />} data={gaps} />
      </VictoryChart>
    </div>
  )
}

export default memo(Chart)
