import type {ReactNode} from 'react'

import BuildsFetcher from '../../../../../containers/BuildsFetcher'
import {useQueryParam} from '../../../../../hooks/routes'
import type {BuildId} from '../../../../../types'
import {useMode} from '../../../../common/ModeSwitch/ModeSwitch'
import {SnapshotDependenciesModes} from '../DependenciesTab.modes'
import {getSnapshotDependenciesLocator} from '../DependenciesTab.utils'

interface Props {
  buildId: BuildId
  children: ReactNode
}

function DependenciesTabBuildsFetcher({buildId, children}: Props) {
  const mode = useMode()

  const stateFilter = useQueryParam('state')

  const withRunningAndQueued = !['successful', 'failed'].includes(stateFilter!)

  return (
    <BuildsFetcher
      fetchCount={1000}
      withProgress={false}
      withRunning={withRunningAndQueued}
      withQueued={withRunningAndQueued}
      withRunningAndQueued={withRunningAndQueued}
      withSnapshotDependencies
      withBuildDetails={mode === SnapshotDependenciesModes.LIST}
      baseLocator={getSnapshotDependenciesLocator(buildId, mode)}
      projectOrBuildTypeNode={{
        nodeType: 'all',
      }}
    >
      {children}
    </BuildsFetcher>
  )
}

export default DependenciesTabBuildsFetcher
