import * as React from 'react'
import {useEffect} from 'react'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'

import BuildLineLayout from '../../../../containers/BuildLineLayout'
import {BuildSelectionIdProvider} from '../../../../contexts/buildSelection'
import {getBuildSnapshotDependencies} from '../../../../selectors'
import type {BuildId} from '../../../../types'
import {stringifyId} from '../../../../types'
import {sortByStarted} from '../../../../utils/startedBefore'
import {UserProperties} from '../../../../utils/userProperties'
import BuildBatchActions from '../../../common/Builds/BuildBatchActions/BuildBatchActions'
import Builds from '../../../common/Builds/Builds.container'
import BuildsFilters from '../../../common/BuildsFilters/BuildsFilters.container'
import ModeSwitch, {Mode, useMode} from '../../../common/ModeSwitch/ModeSwitch'
import BuildPager from '../../../common/Pager/BuildPager/BuildPager.container'
import {submitPager} from '../../../common/Pager/Pager.actions.base'

import type {DependenciesTabQuery} from './__generated__/DependenciesTabQuery.graphql'
import ArtifactDependencies from './ArtifactDependencies/ArtifactDependencies'
import DependenciesTabBuildsFetcher from './DependenciesBuildsFetcher/DependenciesBuildsFetcher'
import DependenciesChain from './DependenciesChain/DependenciesChain'
import {DependenciesTypes, SnapshotDependenciesModes} from './DependenciesTab.modes'
import {dependenciesTabQuery} from './DependenciesTab.queries'
import DependenciesTimeline from './DependenciesTimeline/DependenciesTimeline'
import DependenciesTimelineSearch from './DependenciesTimeline/DependenciesTimelineSearch/DependenciesTimelineSearch'

import styles from './DependenciesTab.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

const directOrder = sortByStarted(true)

type Props = {
  buildId: BuildId
}

type Queries = {
  main: DependenciesTabQuery
}

const pageSize = 100

function DependenciesTab({queries, props}: EntryPointProps<Queries, {}, Props, {}>) {
  const {buildId} = props
  const {buildTypes, chainBuilds, downloadedArtifactBuilds, deliveredArtifactBuilds} =
    usePreloadedQuery(dependenciesTabQuery, queries.main)
  const hasChain = Boolean(chainBuilds?.count || buildTypes?.count)
  const noDependencies = useAppSelector(
    state => getBuildSnapshotDependencies(state, buildId).length === 0,
  )
  const dispatch = useAppDispatch()
  useEffect(() => {
    dispatch(submitPager({pageSize}))
  }, [dispatch])
  const hasDownloadedArtifacts = Boolean(downloadedArtifactBuilds?.count)
  const hasDeliveredArtifacts = Boolean(deliveredArtifactBuilds?.count)
  const mode = useMode(SnapshotDependenciesModes.TIMELINE)
  return (
    <ModeSwitch
      className={styles.typeSwitch}
      userProperty={UserProperties.DEPENDENCIES_TYPE}
      preserveParams={({buildTab}) => ({buildTab})}
      param="type"
    >
      <Mode
        mode={DependenciesTypes.SNAPSHOT}
        label="Snapshot dependencies"
        isForbidden={!hasChain}
        isDisabled={!hasChain}
      >
        <DependenciesTabBuildsFetcher buildId={buildId}>
          <ModeSwitch
            userProperty={UserProperties.DEPENDENCIES_MODE}
            preserveParams={({buildTab, type}) => ({
              buildTab,
              type,
            })}
            customItems={
              mode === SnapshotDependenciesModes.TIMELINE && <DependenciesTimelineSearch />
            }
          >
            <Mode
              mode={SnapshotDependenciesModes.TIMELINE}
              label="Timeline"
              isForbidden={noDependencies}
              isDisabled={noDependencies}
            >
              <DependenciesTimeline />
            </Mode>
            <Mode
              mode={SnapshotDependenciesModes.LIST}
              label="List"
              isForbidden={noDependencies}
              isDisabled={noDependencies}
            >
              <BuildLineLayout isDependencies>
                <BuildsFilters
                  disableAdvancedMode
                  withStateFilter
                  withRunningAndQueued
                  withBuildNamePatternFilter
                />
                <BuildSelectionIdProvider>
                  <Builds
                    sortBy={directOrder}
                    alwaysShowLineBorders
                    withLoader
                    withClientPager
                    withClientFilter
                  />
                  <BuildBatchActions message />
                </BuildSelectionIdProvider>
                <BuildPager isHideWarningComponent />
              </BuildLineLayout>
            </Mode>
            <Mode mode={SnapshotDependenciesModes.CHAIN} label="Chain">
              <DependenciesChain key={stringifyId(buildId)} />
            </Mode>
          </ModeSwitch>
        </DependenciesTabBuildsFetcher>
      </Mode>
      <Mode
        mode={DependenciesTypes.DOWNLOADED_ARTIFACTS}
        label="Downloaded artifacts"
        isForbidden={!hasDownloadedArtifacts}
        isDisabled={!hasDownloadedArtifacts}
      >
        <ArtifactDependencies />
      </Mode>
      <Mode
        mode={DependenciesTypes.DELIVERED_ARTIFACTS}
        label="Delivered artifacts"
        isForbidden={!hasDeliveredArtifacts}
        isDisabled={!hasDeliveredArtifacts}
      >
        <ArtifactDependencies />
      </Mode>
    </ModeSwitch>
  )
}

export type DependenciesTabComponent = typeof DependenciesTab

export default React.memo(DependenciesTab)
