import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import {skipToken} from '@reduxjs/toolkit/query'
import {useMemo} from 'react'

import {useProjectData} from '../../../../../hooks/useEntity'
import {getSingleProjectArg} from '../../../../../rest/projects'
import {getBuildType} from '../../../../../selectors'
import {restApi} from '../../../../../services/rest'
import type {BuildTypeId} from '../../../../../types'

import {getSearch} from './DependenciesTimeline.selectors'

import {useAppSelector} from 'src/hooks/react-redux'

const useBuildTypeName = (buildType: BuildTypeId | undefined) => {
  const projectId = useAppSelector(state =>
    buildType != null ? getBuildType(state, buildType)?.projectId : undefined,
  )
  restApi.endpoints.getProjectNormalized.useQuerySubscription(
    projectId != null ? getSingleProjectArg(projectId) : skipToken,
  )

  const virtual = useProjectData(
    {
      projectId,
    },
    project => project?.virtual,
  )
  const projectName = useProjectData(
    {
      projectId,
    },
    project => project?.name,
  )

  const buildTypeName = useAppSelector(state => getBuildType(state, buildType)?.name ?? '')

  return {
    projectName: virtual ? projectName : undefined,
    buildTypeName,
  }
}

export function useSearchMatch(buildTypeId?: BuildTypeId) {
  const search = useAppSelector(getSearch)
  // we need to use new name here
  const {projectName, buildTypeName} = useBuildTypeName(buildTypeId)
  const projectNameSearch = useMemo(
    () =>
      projectName != null ? fuzzyHighlight(search, projectName) : {matched: false, matches: []},
    [projectName, search],
  )

  const buildTypeNameSearch = useMemo(
    () =>
      buildTypeName != null ? fuzzyHighlight(search, buildTypeName) : {matched: false, matches: []},
    [buildTypeName, search],
  )
  const matched = projectNameSearch.matched || buildTypeNameSearch.matched

  return {
    projectName,
    buildTypeName,
    projectNameSearch,
    buildTypeNameSearch,
    matched,
  }
}
