import {useMemo, useCallback, useRef, useEffect} from 'react'
import type {DomainTuple} from 'victory-core'

import {useQueryParam, useSetQueryParam} from '../../../../../hooks/routes'

import type {Domain, TimeDataWithCoordinates} from './DependenciesTimeline.types'

function getAdjustedDomain(
  domain: DomainTuple,
  datum: TimeDataWithCoordinates | null | undefined,
): DomainTuple {
  if (datum == null) {
    return domain
  }

  const {y, y0} = datum
  const length = y - y0

  if (domain == null || length > Number(domain[1]) - Number(domain[0])) {
    return [y0, y]
  }

  const leftOverflow = Number(domain[0]) - y0

  if (leftOverflow > 0) {
    return [Number(domain[0]) - leftOverflow, Number(domain[1]) - leftOverflow]
  }

  const rightOverflow = y - Number(domain[1])

  if (rightOverflow > 0) {
    return [Number(domain[0]) + rightOverflow, Number(domain[1]) + rightOverflow]
  }

  return domain
}

function parseRange(range: string | null | undefined): [number, number] | null | undefined {
  if (range == null) {
    return null
  }

  const parsedRange = range.split('-').map(Number)
  return parsedRange.length >= 2 && !parsedRange.some(isNaN)
    ? [parsedRange[0], parsedRange[1]]
    : null
}

export const stringifyRange = (range: [number, number]): string => range.map(String).join('-')
type Params = {
  ready: boolean
  maxX: number
  firstQueued: number
  selfQueued: number
  lastNonSelfFinished: number | null | undefined
  lastFinished: number
}

function useYDomain({
  ready,
  firstQueued,
  selfQueued,
  lastNonSelfFinished,
  lastFinished,
}: Params): DomainTuple | null {
  const range = useQueryParam('range')
  const parsedRange = useMemo(() => parseRange(range), [range])
  const defaultRange: DomainTuple = useMemo(
    () =>
      lastNonSelfFinished != null
        ? [selfQueued < lastNonSelfFinished ? selfQueued : firstQueued, lastNonSelfFinished]
        : [firstQueued, lastFinished],
    [firstQueued, lastFinished, lastNonSelfFinished, selfQueued],
  )

  if (parsedRange != null) {
    return parsedRange
  }

  return ready ? defaultRange : null
}

type SetYDomain = {
  setYDomain: (arg0: DomainTuple) => unknown
  adjustYDomain: (arg0: TimeDataWithCoordinates | null | undefined) => unknown
}

function useSetYDomain(yDomain: DomainTuple | null) {
  const setRange = useSetQueryParam('range')
  const setYDomain = useCallback(
    (domain: DomainTuple) => setRange(domain.map(String).join('-')),
    [setRange],
  )
  const domainRef = useRef(yDomain)
  useEffect(() => {
    domainRef.current = yDomain
  }, [yDomain])
  return {
    setYDomain,
    adjustYDomain: useCallback(
      (datum: TimeDataWithCoordinates | null | undefined) =>
        domainRef.current && setYDomain(getAdjustedDomain(domainRef.current, datum)),
      [setYDomain],
    ),
  }
}

export default function useDomain(params: Params): [Domain | null, SetYDomain] {
  const {maxX} = params
  const yDomain = useYDomain(params)
  return [
    useMemo(
      () =>
        yDomain && {
          x: [0, maxX],
          y: yDomain,
        },
      [maxX, yDomain],
    ),
    useSetYDomain(yDomain),
  ]
}
