import classNames from 'classnames'
import {memo, useContext, useMemo} from 'react'
import {Bar as VictoryBar} from 'victory'

import {useAppSelector} from '../../../../../../hooks/react-redux'
import {SelectionContext} from '../DependenciesTimeline.contexts'
import {useSearchMatch} from '../DependenciesTimeline.hooks'
import {getIsSearch} from '../DependenciesTimeline.selectors'
import type {TimeDataWithCoordinates} from '../DependenciesTimeline.types'
import {areRelated} from '../utils/areRelated'

import styles from './PreviewBar.module.css'

const previewBarStyle = {
  fill: undefined,
  stroke: undefined,
}
type PreviewBarProps = {
  data?: ReadonlyArray<TimeDataWithCoordinates>
  datum?: TimeDataWithCoordinates
}
function PreviewBar(props: PreviewBarProps) {
  const {datum, data} = props
  const {selected, focused} = useContext(SelectionContext)
  const isSearch = useAppSelector(getIsSearch)
  const {matched} = useSearchMatch(datum?.build.buildType)

  return useMemo(
    () =>
      datum == null || data == null ? null : (
        <VictoryBar
          {...props}
          style={previewBarStyle}
          className={classNames(
            datum.build.state === 'queued'
              ? styles.previewBarQueued
              : datum.build.canceledInfo != null
                ? styles.previewBarCanceled
                : datum.build.status === 'SUCCESS'
                  ? styles.previewBarSuccess
                  : styles.previewBarFailed,
            {
              [styles.previewBarFocused]: focused === datum.build.id,
              [styles.previewBarFade]: isSearch
                ? !matched
                : selected != null && !areRelated(datum.build.id, selected, data),
            },
          )}
        />
      ),
    [data, datum, focused, isSearch, matched, props, selected],
  )
}

export default memo(PreviewBar)
