import {useMemo} from 'react'

import BuildLineLayout from '../../../../../containers/BuildLineLayout'
import BuildsFetcher from '../../../../../containers/BuildsFetcher'
import {useBuildId, useQueryParam} from '../../../../../hooks/routes'
import type {ProjectOrBuildTypeNode} from '../../../../../types'
import Builds from '../../../../common/Builds/Builds.container'
import BuildPager from '../../../../common/Pager/BuildPager/BuildPager.container'
import {DependenciesTypes} from '../DependenciesTab.modes'

const projectOrBuildTypeNodeAll: ProjectOrBuildTypeNode = {
  nodeType: 'all',
}

export default function ArtifactDependencies() {
  const isDownloaded = useQueryParam('type') === DependenciesTypes.DOWNLOADED_ARTIFACTS
  const buildId = useBuildId()

  const state = isDownloaded ? 'state:(running:true,finished:true)' : 'state:finished'
  const direction = isDownloaded ? 'to' : 'from'
  const children = useMemo(
    () => (
      <BuildLineLayout isDependencies artifactDependenciesMode>
        <Builds
          alwaysShowLineBorders
          withLoader
          withClientPager
          pathFilter={projectOrBuildTypeNodeAll}
        />
        <BuildPager />
      </BuildLineLayout>
    ),
    [],
  )

  return (
    <BuildsFetcher
      fetchCount={1000}
      withProgress={false}
      withRunning
      withQueued
      withBuildDetails
      baseLocator={`artifactDependency(${direction}:(id:${buildId}),recursive:false),${state}${
        isDownloaded ? '' : ',composite:false'
      },count:1000`}
      withDownloadedArtifactsFrom={isDownloaded ? null : buildId}
      projectOrBuildTypeNode={projectOrBuildTypeNodeAll}
    >
      {children}
    </BuildsFetcher>
  )
}
